contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val, address _log) public payable {
        require(true);

        bool setMinSumReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }
        require(!setMinSumReverted);

        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool setLogFileReverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        assert(!setLogFileReverted && c.MinSum() == minSumBefore && minSumBefore == _val);
    }

    receive() external payable {}
}

